/** Example words for a school year (0 = Reception, which uses the Year 1 list). */
export function sampleForYear(year) {
  const y = Number(year);
  if (!Number.isFinite(y) || y <= 1) return Y1_SAMPLE; // NaN (unknown year) falls back to the gentlest list
  if (y === 2) return Y2_SAMPLE;
  if (y <= 4) return Y34_SAMPLE;
  return Y56_SAMPLE;
}
